return $input.all().map(item => {
  try {
    const raw = item.json.output;
    const data = typeof raw === 'string'
      ? JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g, '').trim())
      : raw;

    const routes = ['CREATE_TASK', 'ANALYZE_TASK', 'FALLBACK'];
    const route = routes.includes(data?.route)
      ? data.route
      : 'FALLBACK';

    const clean = value =>
      typeof value === 'string' ? value : '';

    return {
      json: {
        route,
        titulo: clean(data?.titulo),
        descripcion: clean(data?.descripcion),
        disciplina: clean(data?.disciplina),
        prioridad: clean(data?.prioridad),
        responsable: clean(data?.responsable),
        fecha_limite: clean(data?.fecha_limite),
        contexto: clean(data?.contexto)
      }
    };
  } catch (error) {
    return {
      json: {
        route: 'FALLBACK',
        titulo: '',
        descripcion: '',
        disciplina: '',
        prioridad: '',
        responsable: '',
        fecha_limite: '',
        contexto: '',
        error: 'No se pudo interpretar la respuesta del Manager'
      }
    };
  }
});

const items = $input.all();

const mensajes = items.flatMap(item => {
  const data = item.json;
  return Array.isArray(data.messages)
    ? data.messages
    : Array.isArray(data)
      ? data
      : [data];
});

return [{
  json: {
    session_id: $('Preparar sesión').first().json.session_id,
    airtable_record_id: $('Preparar contador de mensajes').first().json.airtable_record_id,
    historial: JSON.stringify(mensajes)
  }
}];

const raw = $input.first().json.text;

const resumen = JSON.parse(
  raw.replace(/```(?:json)?|```/g, '').trim()
);

if (
  typeof resumen.asunto_principal !== 'string' ||
  !Array.isArray(resumen.puntos_clave) ||
  typeof resumen.accion_requerida !== 'string'
) {
  throw new Error('El resumen no tiene el formato esperado');
}

return [{
  json: {
    airtable_record_id: $('Preparar historial').first().json.airtable_record_id,
    resumen: JSON.stringify(resumen),
    datos_clave: resumen.puntos_clave.join('; ')
  }
}];

