const msg = $input.first().json;

const rawFrom = String(msg.From || msg.from || '');

const email = (
  rawFrom.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || ''
).toLowerCase();

const subject = String(
  msg.Subject || msg.subject || ''
).slice(0, 180);

const body = String(
  msg.textPlain ||
  msg.text ||
  msg.snippet ||
  ''
).slice(0, 5000);

const message_id = String(msg.id || '');

return [{
  json: {
    from_email: email,
    subject,
    body_text: body,
    message_id,
    source: 'gmail_support'
  }
}];

const respuesta = $input.first().json;
const raw = $('TP4 - Normalizar entrada').first().json;

const texto = String(respuesta.text || respuesta.output || '').trim();

let datos;
let requiereRevision = false;

try {
  const limpio = texto
    .replace(/```(?:json)?/gi, '')
    .replace(/```/g, '')
    .trim();

  const inicio = limpio.indexOf('{');
  const fin = limpio.lastIndexOf('}');

  if (inicio === -1 || fin < inicio) {
    throw new Error('No se encontró JSON');
  }

  datos = JSON.parse(limpio.slice(inicio, fin + 1));

  if (!datos || Array.isArray(datos) || typeof datos !== 'object') {
    throw new Error('Formato inesperado');
  }
} catch (error) {
  requiereRevision = true;
  datos = {
    categoria: 'otro',
    asunto_borrador: '',
    cuerpo_borrador: texto,
    resumen_interno: 'Revisar respuesta no estructurada de IA'
  };
}

const limpiar = (valor, max) =>
  String(valor ?? '').trim().slice(0, max);

return [{
  json: {
    from_email: raw.from_email,
    subject: raw.subject,
    body_text: raw.body_text,
    message_id: raw.message_id,
    categoria: limpiar(datos.categoria || 'otro', 40),
    draft_subject: limpiar(
      datos.asunto_borrador || 'Re: ' + (raw.subject || 'Consulta'),
      180
    ),
    draft_body: limpiar(datos.cuerpo_borrador, 3000),
    summary: limpiar(datos.resumen_interno, 500),
    requiere_revision: requiereRevision
  }
}];
